mapper.select:
SELECT io.batch_no AS batchNo, tpTask.time_value AS timeValue, tpTask.time_unit AS timeUnit, ier.value_number AS valueNumber, ier.value_text AS valueText FROM lm_inspection_entry_record ier INNER JOIN lm_task t ON ier.task_id = t.id AND t.is_deleted = 0 INNER JOIN lm_inspection_order io ON t.inspection_order_id = io.id AND io.is_deleted = 0 INNER JOIN lm_stability_scheme_version ssv ON io.scheme_version_id = ssv.id AND ssv.is_deleted = 0 INNER JOIN lm_stability_plan_timepoint_task tpTask ON tpTask.inspection_order_id = io.id AND tpTask.is_deleted = 0 INNER JOIN lm_stability_scheme_data_point ssdp ON ier.data_point_config_id = ssdp.id AND ssdp.is_deleted = 0 WHERE ier.is_deleted = 0 AND io.order_status = 'COMPLETED' AND ssv.id = #{query.versionId} AND tpTask.experiment_type = #{query.experimentType} AND tpTask.storage_condition = #{query.storageCondition} AND ssdp.parameter_id = #{query.parameterId} AND ssdp.name = #{query.dataPointName}
AND io.batch_no = #{query.batchNo}
ORDER BY io.batch_no, tpTask.time_value
